public class SettlementService {                // open unless you write final
    private final SettlementLedger ledger;

    public SettlementService(SettlementLedger ledger) {
        this.ledger = ledger;
    }

    @Timed
    public String settle(String batch) {          // overridable
        audit(batch);                             // self-call: intercepted in a subclass
        ledger.post(batch);
        return "settled " + batch;
    }

    @Timed
    public void audit(String batch) { /* ... */ }

    public final String region() { return "EU"; }   // final on purpose: not intercepted
}

