public final class AuditInterceptor implements Interceptor {
    private final List<String> trail;

    public AuditInterceptor(List<String> trail) { this.trail = trail; }

    @Override
    public Object intercept(Invocation inv) {
        trail.add(inv.getName() + Arrays.toString(inv.getArgs()));   // 1. record first
        return inv.proceed();                                        // 2. then carry on
    }
}

