class AuditInterceptor(private val trail: MutableList<String>) : Interceptor {
    override fun intercept(inv: Invocation): Any? {
        trail += inv.name + inv.args.contentToString()             // 1. record first
        return inv.proceed()                                        // 2. then carry on
    }
}

