List<Interceptor> chainFor(Method m) {
    List<Interceptor> chain = new ArrayList<>();
    if (m.isAnnotationPresent(Timed.class)) chain.add(new TimedInterceptor(log, clock));
    Retry r = m.getAnnotation(Retry.class);
    if (r != null) chain.add(new RetryInterceptor(r.attempts(), List.of(r.on())));
    if (m.isAnnotationPresent(Audited.class)) chain.add(new AuditInterceptor(trail));   // 3. innermost
    return chain;
}

