fun chainFor(m: Method): List<Interceptor> = buildList {
    if (m.isAnnotationPresent(Timed::class.java)) add(TimedInterceptor(log, clock))
    m.getAnnotation(Retry::class.java)?.let { add(RetryInterceptor(it.attempts, it.on.map { k -> k.java })) }
    if (m.isAnnotationPresent(Audited::class.java)) add(AuditInterceptor(trail))       // 3. innermost
}

