class InterceptingHandler(
    private val target: Any,
    private val chains: Map<Method, List<Interceptor>>,
) : InvocationHandler {
    override fun invoke(proxy: Any, method: Method, args: Array<Any?>?): Any? {
        val a = args ?: emptyArray()
        if (method.declaringClass == Any::class.java) return when (method.name) {   // 1. identity
            "equals" -> proxy === a[0]
            "hashCode" -> System.identityHashCode(proxy)
            else -> "Proxy[$target]"
        }
        if (method.isDefault) return InvocationHandler.invokeDefault(proxy, method, *a)   // 2. this = proxy
        return Invocation("${method.declaringClass.simpleName}.${method.name}", a, chains[method].orEmpty()) {
            try { method.invoke(target, *a) }                                       // 3. the chain, then the target
            catch (e: InvocationTargetException) { throw e.cause!! }                // 4. unwrap
        }.proceed()
    }
}

