final class InterceptingHandler implements InvocationHandler {
    private final Object target;
    private final Map<Method, List<Interceptor>> chains;

    InterceptingHandler(Object target, Map<Method, List<Interceptor>> chains) {
        this.target = target;
        this.chains = chains;
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        Object[] a = args == null ? new Object[0] : args;
        if (method.getDeclaringClass() == Object.class) {                    // 1. identity
            return switch (method.getName()) {
                case "equals" -> proxy == a[0];
                case "hashCode" -> System.identityHashCode(proxy);
                default -> "Proxy[" + target + "]";
            };
        }
        if (method.isDefault()) return InvocationHandler.invokeDefault(proxy, method, a);   // 2. this = proxy
        String name = method.getDeclaringClass().getSimpleName() + "." + method.getName();
        return new Invocation(name, a, chains.getOrDefault(method, List.of()), () -> {
            try { return method.invoke(target, a); }                         // 3. the chain, then the target
            catch (InvocationTargetException e) { throw sneaky(e.getCause()); }   // 4. unwrap
        }).proceed();
    }

    // Callable.call() may throw Exception but not Throwable: rethrow the cause unchanged
    @SuppressWarnings("unchecked")
    private static <E extends Throwable> E sneaky(Throwable t) throws E { throw (E) t; }
}
